L137: export function identifyImage(bytes, { allowGif = false } = {}) {
L138:   if (bytes.length >= 8 && bytes.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]))) return { extension: 'png', mimeType: 'image/png' };
L139:   if (bytes.length >= 3 && bytes[0] === 255 && bytes[1] === 216 && bytes[2] === 255) return { extension: 'jpg', mimeType: 'image/jpeg' };
L140:   if (bytes.length >= 12 && bytes.toString('ascii', 0, 4) === 'RIFF' && bytes.toString('ascii', 8, 12) === 'WEBP') return { extension: 'webp', mimeType: 'image/webp' };
L141:   if (allowGif && ['GIF87a', 'GIF89a'].includes(bytes.toString('ascii', 0, 6))) return { extension: 'gif', mimeType: 'image/gif' };
L142:   throw new EmomoError('INVALID_IMAGE', 'The image is not a supported PNG, JPEG, WebP, or permitted GIF.');
L143: }
L144: 
L145: export class EmomoClient {
L146:   constructor({ baseUrl = DEFAULT_API_URL, token, timeoutMs = 30000, imageHosts = ['images.timmyagentic.si', 'r2.emomo.net', '*.r2.dev', '*.r2.cloudflarestorage.com'] } = {}) {
L147:     this.base = apiUrl(baseUrl);
L148:     this.token = token;
L149:     this.officialImageToken = token && this.base.href.replace(/\/+$/, '') === DEFAULT_API_URL ? token : undefined;
L150:     this.timeoutMs = timeoutMs;
L151:     this.imageHosts = imageHosts;
L152:     if (token && this.base.protocol !== 'https:') throw new EmomoError('INSECURE_TOKEN', 'API tokens cannot be sent over HTTP.');
L153:   }
L154: 
L155:   async request(path, { method = 'GET', body } = {}) {
L156:     const official = this.base.href.replace(/\/+$/, '') === DEFAULT_API_URL;
L157:     if (official && !this.token) throw new EmomoError('UNAUTHORIZED', `No access key is configured for the official API. ${OFFICIAL_ACCESS_GUIDANCE}`);
L158:     const url = new URL(`${this.base.href.replace(/\/$/, '')}/${path}`);
L159:     const headers = { Accept: 'application/json', 'User-Agent': USER_AGENT };
L160:     if (body !== undefined) headers['Content-Type'] = 'application/json';
L161:     if (this.token) headers.Authorization = `Bearer ${this.token}`;
L162:     const response = await this.fetch(url, { method, headers, body: body === undefined ? undefined : JSON.stringify(body), redirect: 'manual' });
L163:     if (response.status >= 300 && response.status < 400) {
L164:       await response.body?.cancel();
L165:       throw new EmomoError('API_REDIRECT', 'API redirects are not followed. Configure the final API URL explicitly.');
L166:     }
L167:     if (!response.ok) {
L168:       await response.body?.cancel();
L169:       throw statusError(response, 'API', official);
L170:     }
L171:     if (!response.headers.get('content-type')?.toLowerCase().includes('application/json')) {
L172:       await response.body?.cancel();
L173:       throw invalidResponse();
L174:     }
L175:     let result;
L176:     try { result = JSON.parse((await readBounded(response, MAX_JSON_BYTES)).toString('utf8')); } catch (error) {
L177:       if (error instanceof EmomoError) throw error;
L178:       throw invalidResponse();
L179:     }
L180:     if (!object(result)) throw invalidResponse();
L181:     return result;
L182:   }
L183: 
L184:   async fetch(url, options) {
L185:     try { return await fetch(url, { ...options, signal: AbortSignal.timeout(this.timeoutMs) }); } catch (error) {
L186:       throw transportError(error);
L187:     }

