const HOP_BY_HOP_REQUEST_HEADERS = new Set([
  'connection',
  'content-length',
  'host',
  'keep-alive',
  'proxy-authenticate',
  'proxy-authorization',
  'te',
  'trailer',
  'transfer-encoding',
  'upgrade',
]);

const HOP_BY_HOP_RESPONSE_HEADERS = new Set([
  'connection',
  'keep-alive',
  'proxy-authenticate',
  'proxy-authorization',
  'te',
  'trailer',
  'transfer-encoding',
  'upgrade',
]);

const UPSTREAM_RESPONSE_HEADERS_TO_STRIP = [
  /^access-control-/i,
  /^x-proxied-/i,
];

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const corsHeaders = getCorsHeaders(request, env);
    const agentMode = String(env.SERVICE_MODE) !== 'legacy';
    let routedRequest = request;

    if (agentMode) {
      const pathname = new URL(request.url).pathname;
      if (/^\/api\/v1(?:\/|$)/.test(pathname)) {
        return pausedResponse(corsHeaders);
      }
      const mapped = mapAgentRequest(request);
      if (!mapped) {
        return jsonError(404, 'not_found', 'This Agent API route is not exposed.', corsHeaders);
      }
      if (String(env.AGENT_API_ENABLED) !== 'true') {
        return pausedResponse(corsHeaders);
      }
      routedRequest = mapped;
    }

    if (request.method === 'OPTIONS') {
      return handleOptions(routedRequest, corsHeaders);
    }

    if (!env.HF_TOKEN) {
      return jsonError(500, 'missing_gateway_secret', 'Gateway is missing HF_TOKEN.', corsHeaders);
    }

    const route = matchRoute(routedRequest);
    if (!route) {
      return jsonError(404, 'not_found', 'This API route is not exposed by the gateway.', corsHeaders);
    }

    const validation = await validateRequest(routedRequest, route, env);
    if (validation.error) {
      return jsonError(validation.error.status, validation.error.code, validation.error.message, corsHeaders);
    }
    if (agentMode && routedRequest.method === 'POST') {
      const agentValidation = validateAgentSearchBody(validation.body, env);
      if (agentValidation.error) {
        return jsonError(agentValidation.error.status, agentValidation.error.code, agentValidation.error.message, corsHeaders);
      }
      validation.body = agentValidation.body;
    }

    const rateLimitError = await enforceRateLimit(request, route, env);
    if (rateLimitError) {
      return jsonError(rateLimitError.status, rateLimitError.code, rateLimitError.message, corsHeaders);
    }

    if (route.cacheable) {
      const cached = await caches.default.match(request);
      if (cached) {
        return withCorsHeaders(cached, corsHeaders, 'HIT');
      }
    }

    const upstreamRequest = buildUpstreamRequest(routedRequest, env, validation.body);
    const upstreamResponse = await fetch(upstreamRequest);
    const response = buildClientResponse(
      upstreamResponse,
      corsHeaders,
      Boolean(route.cacheable),
      parsePositiveInteger(env.CACHE_TTL_SECONDS, 30)
    );

    if (route.cacheable && response.ok) {
      ctx.waitUntil(caches.default.put(request, response.clone()));
    }

    return response;
  },
};

// The Agent surface shares the existing backend DTOs, without reopening legacy
// clients, streaming LLM traces, bulk browsing, or administrative routes.
function mapAgentRequest(request: Request): Request | undefined {
  const url = new URL(request.url);
  if (!/^\/agent\/v1\/(?:search|categories|stats|memes\/[a-zA-Z0-9_-]+)$/.test(url.pathname)) {
    return undefined;
  }
  url.pathname = url.pathname.replace(/^\/agent\/v1/, '/api/v1');
  return new Request(url.toString(), request);
}

function pausedResponse(corsHeaders: HeadersInit): Response {
  return new Response(JSON.stringify({ error: 'SERVICE_PAUSED', message: 'Emomo is temporarily offline.' }), {
    status: 410,
    headers: {
      ...Object.fromEntries(new Headers(corsHeaders)),
      'Content-Type': 'application/json; charset=utf-8',
      'Cache-Control': 'no-store',
      'X-Emomo-Service-State': 'paused',
    },
  });
}

function validateAgentSearchBody(body: Uint8Array | undefined, env: Env): ValidationResult {
  let payload: unknown;
  try { payload = JSON.parse(new TextDecoder().decode(body)); } catch {
    return { error: { status: 400, code: 'invalid_json', message: 'Search body must be a JSON object.' } };
  }
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    return { error: { status: 400, code: 'invalid_search', message: 'Search body must be a JSON object.' } };
  }
  const record = payload as Record<string, unknown>;
  if (typeof record.query !== 'string' || !record.query.trim() || [...record.query.trim()].length > 160) {
    return { error: { status: 400, code: 'invalid_query', message: 'Search query must contain 1–160 characters.' } };
  }
  const topK = record.top_k ?? record.topK ?? 8;
  if (typeof topK !== 'number' || !Number.isInteger(topK) || topK < 1 || topK > parsePositiveInteger(env.MAX_SEARCH_TOP_K, 100)) {
    return { error: { status: 400, code: 'invalid_top_k', message: 'Search top_k must be a positive integer within the gateway limit.' } };
  }
  record.query = record.query.trim();
  record.top_k = topK;
  delete record.topK;
  return { body: new TextEncoder().encode(JSON.stringify(record)) };
}

function handleOptions(request: Request, corsHeaders: HeadersInit): Response {
  const requestedMethod = request.headers.get('Access-Control-Request-Method')?.toUpperCase();
  const syntheticRequest = new Request(request.url, {
    method: requestedMethod || 'GET',
  });

  if (!requestedMethod || !matchRoute(syntheticRequest)) {
    return new Response(null, { status: 404, headers: corsHeaders });
  }

  return new Response(null, {
    status: 204,
    headers: corsHeaders,
  });
}

function matchRoute(request: Request): Route | undefined {
  const url = new URL(request.url);
  const method = request.method.toUpperCase();
  return ALLOWED_ROUTES.find((route) => route.method === method && route.pattern.test(url.pathname));
}

async function validateRequest(
  request: Request,
  route: Route,
  env: Env
): Promise<ValidationResult> {
  const url = new URL(request.url);

  for (const key of url.searchParams.keys()) {
    if (!route.queryParams.has(key)) {
      return {
        error: {
          status: 400,
          code: 'unsupported_query_parameter',
          message: `Query parameter "${key}" is not supported for this endpoint.`,
        },
      };
    }
  }

  if (request.method === 'GET' && url.pathname === '/api/v1/memes') {
    const maxListWindow = parsePositiveInteger(env.MAX_LIST_WINDOW, 120);
    const limit = parseNonNegativeInteger(url.searchParams.get('limit'), 20);
    const offset = parseNonNegativeInteger(url.searchParams.get('offset'), 0);
    if (offset + Math.max(limit, 1) > maxListWindow) {
      return {
        error: {
          status: 403,
          code: 'bulk_listing_blocked',
          message: 'Meme listing is limited to the public browse window.',
        },
      };
    }
  }

  if (request.method === 'POST') {
    const contentType = request.headers.get('content-type') || '';
    if (!contentType.toLowerCase().startsWith('application/json')) {
      return {
        error: {
          status: 415,
          code: 'unsupported_media_type',
          message: 'POST requests must use application/json.',
        },
      };
    }

    const maxBodyBytes = parsePositiveInteger(env.MAX_REQUEST_BODY_BYTES, 65536);
    const contentLength = request.headers.get('content-length');
    if (contentLength && Number(contentLength) > maxBodyBytes) {
      return {
        error: {
          status: 413,
          code: 'request_too_large',
          message: 'Request body exceeds the gateway limit.',
        },
      };
    }

    const bodyResult = await readRequestBody(request, maxBodyBytes);
    if (bodyResult.error) {
      return { error: bodyResult.error };
    }
    const topKError = validateSearchBodyTopK(url.pathname, bodyResult.body, env);
    if (topKError) {
      return { error: topKError };
    }
    return { body: bodyResult.body };
  }

  return {};
}

async function enforceRateLimit(
  request: Request,
  route: Route,
  env: Env
): Promise<{ status: number; code: string; message: string } | undefined> {
  if (!route.rateLimitKey) {
    return undefined;
  }

  const limiter = env.EMOMO_RATE_LIMITER;
  if (!limiter) {
    return {
      status: 500,
      code: 'missing_rate_limiter',
      message: 'Gateway is missing its rate limiter binding.',
    };
  }

  const { success } = await limiter.limit({
    key: `${route.rateLimitKey}:${clientRateLimitKey(request)}`,
  });
  if (success) {
    return undefined;
  }

  return {
    status: 429,
    code: 'rate_limited',
    message: 'Too many requests. Please slow down.',
  };
}

function buildUpstreamRequest(request: Request, env: Env, body?: Uint8Array): Request {
  const incomingUrl = new URL(request.url);
  const upstreamUrl = new URL(incomingUrl.pathname + incomingUrl.search, env.UPSTREAM_ORIGIN);
  const headers = new Headers();

  for (const [key, value] of request.headers) {
    const normalized = key.toLowerCase();
    if (HOP_BY_HOP_REQUEST_HEADERS.has(normalized) || normalized === 'authorization') {
      continue;
    }
    headers.set(key, value);
  }

  headers.set('Accept', request.headers.get('Accept') || 'application/json');
  headers.set('Authorization', `Bearer ${env.HF_TOKEN}`);
  headers.set('X-Forwarded-Host', incomingUrl.host);
  headers.set('X-Forwarded-Proto', incomingUrl.protocol.replace(':', ''));

  return new Request(upstreamUrl.toString(), {
    method: request.method,
    headers,
    body: request.method === 'GET' || request.method === 'HEAD' ? null : body,
    redirect: 'manual',
  });
}

function buildClientResponse(
  upstreamResponse: Response,
  corsHeaders: HeadersInit,
  cacheable: boolean,
  cacheTtlSeconds: number
): Response {
  const headers = new Headers(upstreamResponse.headers);

  for (const header of HOP_BY_HOP_RESPONSE_HEADERS) {
    headers.delete(header);
  }

  for (const header of [...headers.keys()]) {
    if (UPSTREAM_RESPONSE_HEADERS_TO_STRIP.some((pattern) => pattern.test(header))) {
      headers.delete(header);
    }
  }

  headers.delete('set-cookie');
  headers.set('X-Content-Type-Options', 'nosniff');

  for (const [key, value] of new Headers(corsHeaders)) {
    headers.set(key, value);
  }

  if (cacheable && upstreamResponse.ok && isCacheableResponse(upstreamResponse)) {
    headers.set('Cache-Control', `public, max-age=${cacheTtlSeconds}`);
  } else if (!headers.has('Cache-Control')) {
    headers.set('Cache-Control', 'no-store');
  }

  return new Response(upstreamResponse.body, {
    status: upstreamResponse.status,
    statusText: upstreamResponse.statusText,
    headers,
  });
}

function isCacheableResponse(response: Response): boolean {
  const contentType = response.headers.get('content-type') || '';
  return contentType.includes('application/json');
}

function getCorsHeaders(request: Request, env: Env): HeadersInit {
  const origin = request.headers.get('Origin');
  const allowedOrigin = resolveAllowedOrigin(origin, env.CORS_ALLOWED_ORIGINS);
  const headers: Record<string, string> = {
    'Access-Control-Allow-Methods': 'GET,POST,OPTIONS',
    'Access-Control-Allow-Headers': 'Accept,Content-Type',
    'Access-Control-Max-Age': '86400',
  };

  if (allowedOrigin) {
    headers['Access-Control-Allow-Origin'] = allowedOrigin;
    headers['Vary'] = 'Origin';
  }

  return headers;
}

function resolveAllowedOrigin(origin: string | null, configuredOrigins: string): string | undefined {
  if (!origin) {
    return undefined;
  }

  const origins = configuredOrigins
    .split(',')
    .map((entry) => entry.trim())
    .filter(Boolean);

  if (origins.includes('*')) {
    return '*';
  }

  return origins.includes(origin) ? origin : undefined;
}

function withCorsHeaders(response: Response, corsHeaders: HeadersInit, cacheStatus: 'HIT' | 'MISS'): Response {
  const headers = new Headers(response.headers);
  for (const [key, value] of new Headers(corsHeaders)) {
    headers.set(key, value);
  }
  headers.set('X-Emomo-Gateway-Cache', cacheStatus);

  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

function jsonError(status: number, code: string, message: string, corsHeaders: HeadersInit): Response {
  return new Response(JSON.stringify({ error: { code, message } }), {
    status,
    headers: {
      ...Object.fromEntries(new Headers(corsHeaders)),
      'Cache-Control': 'no-store',
      'Content-Type': 'application/json; charset=utf-8',
      'X-Content-Type-Options': 'nosniff',
    },
  });
}

function parsePositiveInteger(value: string | undefined, fallback: number): number {
  if (!value) {
    return fallback;
  }
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
}

function parseNonNegativeInteger(value: string | null, fallback: number): number {
  if (!value) {
    return fallback;
  }
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : fallback;
}

async function readRequestBody(
  request: Request,
  maxBodyBytes: number
): Promise<{
  body: Uint8Array;
  error?: { status: number; code: string; message: string };
}> {
  const reader = request.body?.getReader();
  if (!reader) {
    return { body: new Uint8Array() };
  }

  const chunks: Uint8Array[] = [];
  let totalBytes = 0;

  while (true) {
    const { done, value } = await reader.read();
    if (done) {
      break;
    }
    totalBytes += value.byteLength;
    if (totalBytes > maxBodyBytes) {
      await reader.cancel();
      return {
        body: new Uint8Array(),
        error: {
          status: 413,
          code: 'request_too_large',
          message: 'Request body exceeds the gateway limit.',
        },
      };
    }
    chunks.push(value);
  }

  const body = new Uint8Array(totalBytes);
  let offset = 0;
  for (const chunk of chunks) {
    body.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return { body };
}

function validateSearchBodyTopK(
  pathname: string,
  body: Uint8Array,
  env: Env
): { status: number; code: string; message: string } | undefined {
  if (pathname !== '/api/v1/search' && pathname !== '/api/v1/search/stream') {
    return undefined;
  }
  if (body.byteLength === 0) {
    return undefined;
  }

  let payload: unknown;
  try {
    payload = JSON.parse(new TextDecoder().decode(body));
  } catch {
    return {
      status: 400,
      code: 'invalid_json',
      message: 'POST body must be valid JSON.',
    };
  }

  if (!payload || typeof payload !== 'object') {
    return undefined;
  }
  const record = payload as Record<string, unknown>;
  const rawTopK = record.topK ?? record.top_k;
  if (rawTopK === undefined) {
    return undefined;
  }
  const topK = typeof rawTopK === 'number' ? rawTopK : Number(rawTopK);
  const maxTopK = parsePositiveInteger(env.MAX_SEARCH_TOP_K, 100);
  if (Number.isFinite(topK) && topK > maxTopK) {
    return {
      status: 400,
      code: 'search_top_k_too_large',
      message: `Search topK is limited to ${maxTopK}.`,
    };
  }
  return undefined;
}

function clientRateLimitKey(request: Request): string {
  return request.headers.get('CF-Connecting-IP') || 'unknown-client';
}

# Emomo Logger 重构计划

## 1. 现状分析

### 1.1 现有实现优势

✅ **已具备的核心能力：**
- 基于 logrus 的结构化日志（JSON 格式）
- Context 集成机制（`FromContext`, `WithContext`）
- Fields 支持 (`WithFields`)
- HTTP 请求 ID 追踪（UUID）
- 延迟测量（毫秒级）
- 调用者信息自动报告
- 服务名标识（`ServiceName`）

✅ **日志覆盖完整：**
- 196 处日志调用
- 涵盖 API、摄取、搜索等核心业务流程
- 清晰的日志级别区分（Info/Warn/Error/Debug）

### 1.2 需要改进的方面

❌ **缺失的关键特性：**

| 特性 | 现状 | 影响 |
|------|------|------|
| **追踪字段标准化** | 无 `task_id`, `trace_id`, `component` 标准 | 难以跨服务关联日志 |
| **Context 字段注入** | 需要手动 `WithFields` | 使用繁琐，容易遗漏 |
| **指标/描述分离** | 混用 Fields 和 message | 查询效率低，难以聚合 |
| **简化 API** | 无 `CtxInfo/CtxError` 等便捷函数 | 代码冗长 |
| **环境变量配置** | 仅支持代码配置 | 部署不灵活 |
| **日志轮转** | 无文件轮转支持 | 磁盘可能打满 |
| **输出控制** | 无 stdout/file 分离 | 开发/生产环境体验差 |

---

## 2. 重构目标

### 2.1 核心设计原则

**三层分类设计：**

```
┌─────────────────┬──────────────────┬─────────────────────────┐
│     类型        │    存储位置      │         用途            │
├─────────────────┼──────────────────┼─────────────────────────┤
│ **追踪字段**    │ Context → JSON   │ 贯穿调用链，日志关联    │
│ (task_id)       │                  │ 示例: search_id, job_id │
├─────────────────┼──────────────────┼─────────────────────────┤
│ **指标字段**    │ Entry → JSON     │ 单次日志，聚合/告警     │
│ (duration_ms)   │                  │ 示例: count, size       │
├─────────────────┼──────────────────┼─────────────────────────┤
│ **描述信息**    │ message 字符串   │ 人类阅读                │
│ (url, path)     │                  │ 示例: url=%s, step=%s   │
└─────────────────┴──────────────────┴─────────────────────────┘
```

**判断标准：** 这个字段需要被机器查询/聚合/告警吗？
- **是** → JSON 字段（Context 或 Entry）
- **否** → message 字符串

### 2.2 API 设计目标

```go
// ✅ 理想的使用方式
func IngestMemes(ctx context.Context, source string) error {
    // 1. 入口处注入追踪字段（一次性）
    ctx = logger.WithFields(ctx, logger.Fields{
        logger.FieldComponent: "ingest",
        logger.FieldJobID:     uuid.New().String(),
    })

    // 2. 业务日志简洁清晰
    logger.CtxInfo(ctx, "Starting ingestion: source=%s", source)

    startTime := time.Now()
    err := process(ctx)
    duration := time.Since(startTime)

    // 3. 指标字段单独记录（可聚合）
    if err != nil {
        logger.With(logger.Fields{
            "duration_ms": duration.Milliseconds(),
        }).Error(ctx, "Ingestion failed: source=%s, error=%v", source, err)
        return err
    }

    logger.With(logger.Fields{
        "duration_ms": duration.Milliseconds(),
    }).Info(ctx, "Ingestion completed: source=%s", source)
    return nil
}
```

---

## 3. 重构实施计划

### 阶段一：增强 Logger 核心能力 (Week 1)

#### 3.1 标准追踪字段定义

**文件：** `internal/logger/fields.go`

```go
package logger

// 标准追踪字段（Context 级别，贯穿调用链）
const (
    FieldRequestID = "request_id" // HTTP 请求 ID（已有）
    FieldJobID     = "job_id"     // 数据摄取任务 ID
    FieldSearchID  = "search_id"  // 搜索请求 ID
    FieldComponent = "component"  // 组件/模块名
    FieldSource    = "source"     // 数据源标识
    FieldUserID    = "user_id"    // 用户 ID（预留）

    // OpenTelemetry 分布式追踪字段
    FieldTraceID = "trace_id" // OpenTelemetry Trace ID
    FieldSpanID  = "span_id"  // OpenTelemetry Span ID
)

// 标准指标字段（Entry 级别，用于聚合）
const (
    FieldDurationMs = "duration_ms" // 执行耗时（毫秒）
    FieldCount      = "count"       // 计数
    FieldSize       = "size"        // 数据大小（字节）
    FieldStatus     = "status"      // 状态
)
```

#### 3.2 Context 字段便捷操作

**文件：** `internal/logger/context.go`（扩展现有文件）

```go
// ============================================
// Default Logger 获取函数
// ============================================

// GetDefault 获取默认 logger（线程安全）
// 用于在没有 context 的场景下获取 logger
func GetDefault() *Logger {
    defaultLoggerMu.RLock()
    defer defaultLoggerMu.RUnlock()
    return defaultLogger
}

// getDefaultLogger 内部使用的获取函数
// Entry API 等内部模块使用此函数
func getDefaultLogger() *Logger {
    return GetDefault()
}

// ============================================
// Context 字段注入函数
// ============================================

// 便捷的单字段注入函数
func WithField(ctx context.Context, key string, value interface{}) context.Context {
    log := FromContext(ctx)
    return log.WithField(key, value).WithContext(ctx)
}

// 批量字段注入（已有 ContextWithFields，可重命名为 WithFields）
func WithFields(ctx context.Context, fields Fields) context.Context {
    return ContextWithFields(ctx, fields)
}

// 标准字段的快捷注入函数
func SetRequestID(ctx context.Context, id string) context.Context {
    return WithField(ctx, FieldRequestID, id)
}

func SetJobID(ctx context.Context, id string) context.Context {
    return WithField(ctx, FieldJobID, id)
}

func SetSearchID(ctx context.Context, id string) context.Context {
    return WithField(ctx, FieldSearchID, id)
}

func SetComponent(ctx context.Context, name string) context.Context {
    return WithField(ctx, FieldComponent, name)
}

func SetSource(ctx context.Context, source string) context.Context {
    return WithField(ctx, FieldSource, source)
}

// 字段提取函数
func GetField(ctx context.Context, key string) (interface{}, bool) {
    log := FromContext(ctx)
    val, ok := log.Data[key]
    return val, ok
}

func GetFieldString(ctx context.Context, key string) string {
    val, ok := GetField(ctx, key)
    if !ok {
        return ""
    }
    str, _ := val.(string)
    return str
}

func GetRequestID(ctx context.Context) string {
    return GetFieldString(ctx, FieldRequestID)
}

func GetJobID(ctx context.Context) string {
    return GetFieldString(ctx, FieldJobID)
}

func GetSearchID(ctx context.Context) string {
    return GetFieldString(ctx, FieldSearchID)
}

func GetComponent(ctx context.Context) string {
    return GetFieldString(ctx, FieldComponent)
}

func GetFields(ctx context.Context) Fields {
    log := FromContext(ctx)
    fields := make(Fields, len(log.Data))
    for k, v := range log.Data {
        fields[k] = v
    }
    return fields
}

// ============================================
// OpenTelemetry 集成
// ============================================

import "go.opentelemetry.io/otel/trace"

// InjectTraceID 从 context 提取 OpenTelemetry trace/span ID 并注入 logger
// 用于将分布式追踪与日志关联，便于在 Grafana 等工具中跨服务追踪
//
// 使用示例（在 HTTP 中间件中）:
//
//	func TracingMiddleware() gin.HandlerFunc {
//	    return func(c *gin.Context) {
//	        ctx := c.Request.Context()
//	        ctx = logger.InjectTraceID(ctx)
//	        c.Request = c.Request.WithContext(ctx)
//	        c.Next()
//	    }
//	}
func InjectTraceID(ctx context.Context) context.Context {
    span := trace.SpanFromContext(ctx)
    if !span.SpanContext().IsValid() {
        return ctx
    }
    return WithFields(ctx, Fields{
        FieldTraceID: span.SpanContext().TraceID().String(),
        FieldSpanID:  span.SpanContext().SpanID().String(),
    })
}

// GetTraceID 从 context 获取 trace ID
func GetTraceID(ctx context.Context) string {
    return GetFieldString(ctx, FieldTraceID)
}

// GetSpanID 从 context 获取 span ID
func GetSpanID(ctx context.Context) string {
    return GetFieldString(ctx, FieldSpanID)
}
