#### 3.3 Entry API（指标字段专用）

**文件：** `internal/logger/entry.go`（新建）

```go
package logger

import (
    "context"
)

// Entry 代表一个包含指标字段的日志条目
// 用于记录可聚合的指标（duration_ms, count, size 等）
type Entry struct {
    logger *Logger
    fields Fields
}

// With 创建一个包含指标字段的 Entry
// 示例: logger.With(logger.Fields{"duration_ms": 1234}).Info(ctx, "Task completed")
func With(fields Fields) *Entry {
    return &Entry{
        logger: getDefaultLogger(),
        fields: fields,
    }
}

// With 在现有 Entry 基础上添加更多字段
func (e *Entry) With(fields Fields) *Entry {
    merged := make(Fields, len(e.fields)+len(fields))
    for k, v := range e.fields {
        merged[k] = v
    }
    for k, v := range fields {
        merged[k] = v
    }
    return &Entry{
        logger: e.logger,
        fields: merged,
    }
}

// WithField 添加单个字段
func (e *Entry) WithField(key string, value interface{}) *Entry {
    return e.With(Fields{key: value})
}

// Info 记录 Info 级别日志
func (e *Entry) Info(ctx context.Context, format string, args ...interface{}) {
    log := e.logger
    if ctx != nil {
        log = FromContext(ctx)
    }
    log.WithFields(e.fields).Infof(format, args...)
}

// Warn 记录 Warn 级别日志
func (e *Entry) Warn(ctx context.Context, format string, args ...interface{}) {
    log := e.logger
    if ctx != nil {
        log = FromContext(ctx)
    }
    log.WithFields(e.fields).Warnf(format, args...)
}

// Error 记录 Error 级别日志
func (e *Entry) Error(ctx context.Context, format string, args ...interface{}) {
    log := e.logger
    if ctx != nil {
        log = FromContext(ctx)
    }
    log.WithFields(e.fields).Errorf(format, args...)
}

// Debug 记录 Debug 级别日志
func (e *Entry) Debug(ctx context.Context, format string, args ...interface{}) {
    log := e.logger
    if ctx != nil {
        log = FromContext(ctx)
    }
    log.WithFields(e.fields).Debugf(format, args...)
}

// Fatal 记录 Fatal 级别日志并退出
func (e *Entry) Fatal(ctx context.Context, format string, args ...interface{}) {
    log := e.logger
    if ctx != nil {
        log = FromContext(ctx)
    }
    log.WithFields(e.fields).Fatalf(format, args...)
}
