```go
package logger

import (
    "io"
    "os"
    "strconv"
    "strings"
)

// Config 日志配置
type Config struct {
    // 基础配置
    Level       string    // 日志级别: debug, info, warn, error
    Format      string    // 输出格式: json, text
    Output      io.Writer // 输出目标（优先级最高）
    ServiceName string    // 服务名称

    // 环境配置
    Environment string // 环境: local, dev, prod

    // 文件输出配置
    LogFile     string // 日志文件路径
    LogFileOnly bool   // 仅输出到文件（不输出到 stdout）

    // 日志轮转配置
    MaxSize    int  // 单文件最大 MB
    MaxBackups int  // 保留文件数
    MaxAge     int  // 保留天数
    Compress   bool // 压缩旧日志
}

// LoadFromEnv 从环境变量加载配置
func LoadFromEnv() *Config {
    cfg := &Config{
        Level:       getEnv("LOG_LEVEL", "info"),
        Format:      getEnv("LOG_FORMAT", "json"),
        ServiceName: getEnv("SERVICE_NAME", "emomo"),
        Environment: getEnv("APP_ENV", "local"),

        LogFile:     getEnv("LOG_FILE", "/var/log/emomo/app.log"),
        LogFileOnly: getEnvBool("LOG_FILE_ONLY", false),

        MaxSize:    getEnvInt("LOG_MAX_SIZE", 100),
        MaxBackups: getEnvInt("LOG_MAX_BACKUPS", 7),
        MaxAge:     getEnvInt("LOG_MAX_AGE", 30),
        Compress:   getEnvBool("LOG_COMPRESS", true),
    }

    return cfg
}

// 辅助函数
func getEnv(key, defaultVal string) string {
    if val := os.Getenv(key); val != "" {
        return val
    }
    return defaultVal
}

func getEnvBool(key string, defaultVal bool) bool {
    val := os.Getenv(key)
    if val == "" {
        return defaultVal
    }
    b, _ := strconv.ParseBool(val)
    return b
}

func getEnvInt(key string, defaultVal int) int {
    val := os.Getenv(key)
    if val == "" {
        return defaultVal
    }
    i, err := strconv.Atoi(val)
    if err != nil {
        return defaultVal
    }
    return i
}
