#### 3.6 日志轮转支持

**依赖添加：**
```bash
go get gopkg.in/natefinch/lumberjack.v2
```

**文件：** `internal/logger/logger.go`（修改 New 函数）

```go
import (
    "io"
    "os"

    "github.com/sirupsen/logrus"
    "gopkg.in/natefinch/lumberjack.v2"
)

// New 创建日志器（支持环境变量配置）
func New(cfg *Config) *Logger {
    if cfg == nil {
        cfg = LoadFromEnv()
    }

    log := logrus.New()

    // 设置日志级别
    level, err := logrus.ParseLevel(cfg.Level)
    if err != nil {
        level = logrus.InfoLevel
    }
    log.SetLevel(level)

    // 设置输出格式
    if strings.ToLower(cfg.Format) == "text" {
        log.SetFormatter(&logrus.TextFormatter{
            FullTimestamp:   true,
            TimestampFormat: "2006-01-02T15:04:05.000Z07:00",
        })
    } else {
        log.SetFormatter(&logrus.JSONFormatter{
            TimestampFormat: "2006-01-02T15:04:05.000Z07:00",
            FieldMap: logrus.FieldMap{
                logrus.FieldKeyTime:  "timestamp",
                logrus.FieldKeyLevel: "level",
                logrus.FieldKeyMsg:   "message",
            },
            CallerPrettyfier: func(f *runtime.Frame) (string, string) {
                filename := path.Base(f.File)
                function := path.Base(f.Function)
                return function, fmt.Sprintf("%s:%d", filename, f.Line)
            },
        })
    }

    log.SetReportCaller(true)

    // 配置输出目标
    if cfg.Output != nil {
        // 优先使用显式指定的输出
        log.SetOutput(cfg.Output)
    } else {
        // 根据环境配置输出
        var writers []io.Writer

        // Stdout 输出
        if cfg.Environment == "local" || !cfg.LogFileOnly {
            writers = append(writers, os.Stdout)
        }

        // 文件输出（非 local 环境）
        if cfg.Environment != "local" && cfg.LogFile != "" {
            fileWriter := &lumberjack.Logger{
                Filename:   cfg.LogFile,
                MaxSize:    cfg.MaxSize,    // MB
                MaxBackups: cfg.MaxBackups,
                MaxAge:     cfg.MaxAge,     // days
                Compress:   cfg.Compress,
            }
            writers = append(writers, fileWriter)
        }

        if len(writers) == 0 {
            writers = append(writers, os.Stdout)
        }

        log.SetOutput(io.MultiWriter(writers...))
    }

    // 添加服务名字段
    entry := log.WithField("service", cfg.ServiceName)

    return &Logger{Entry: entry}
}

// NewDefault 创建使用环境变量配置的默认日志器
func NewDefault() *Logger {
    return New(nil)
}
```

#### 3.7 优雅关闭 (Graceful Shutdown)

**文件：** `internal/logger/logger.go`（扩展）

确保程序退出前所有日志被刷新到磁盘，避免日志丢失：

```go
import (
    "io"
    "sync"
)

// writerCloser 保存可关闭的 writer 引用
var (
    writerCloser   io.Closer
    writerCloserMu sync.Mutex
)

// Sync 刷新所有待写入的日志并关闭文件句柄
// 应在程序退出前调用，确保日志不丢失
//
// 使用示例：
//
//	func main() {
//	    // 初始化 logger
//	    logger.SetDefaultLogger(logger.NewDefault())
//	    defer logger.Sync() // 确保退出时刷新日志
//
//	    // ... 业务逻辑
//	}
//
// 或配合 signal 处理：
//
//	sigCh := make(chan os.Signal, 1)
//	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
//	<-sigCh
//	logger.Sync()
func Sync() error {
    writerCloserMu.Lock()
    defer writerCloserMu.Unlock()

    if writerCloser != nil {
        return writerCloser.Close()
    }
    return nil
}

// 在 New() 函数中保存 closer 引用（修改 New 函数）:
// 添加到文件输出配置部分:
//
//	if cfg.Environment != "local" && cfg.LogFile != "" {
//	    fileWriter := &lumberjack.Logger{...}
//	    writers = append(writers, fileWriter)
//
//	    // 保存 closer 引用以便 Sync() 使用
//	    writerCloserMu.Lock()
//	    writerCloser = fileWriter
//	    writerCloserMu.Unlock()
//	}
```

**集成到入口点：**

```go
// cmd/api/main.go
func main() {
    // 初始化
    appLogger := logger.NewDefault()
    logger.SetDefaultLogger(appLogger)

    // 确保退出时刷新日志
    defer func() {
        logger.Info("Shutting down, flushing logs...")
        if err := logger.Sync(); err != nil {
            fmt.Fprintf(os.Stderr, "Failed to sync logger: %v\n", err)
        }
    }()

    // 优雅关闭处理
    ctx, cancel := context.WithCancel(context.Background())
    defer cancel()

    sigCh := make(chan os.Signal, 1)
    signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)

    go func() {
        <-sigCh
        logger.Info("Received shutdown signal")
        cancel()
    }()

    // ... 启动服务
}
```

